package fr.axephir.tnd.gametest;

import fr.axephir.tnd.core.ModContent;
import fr.axephir.tnd.domain.*;
import fr.axephir.tnd.progression.*;
import fr.axephir.tnd.narrative.*;
import fr.axephir.tnd.technology.*;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.*;
import net.minecraft.world.effect.MobEffects;
import net.minecraft.world.entity.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.phys.Vec3;
import net.neoforged.neoforge.common.NeoForge;
import net.neoforged.neoforge.event.entity.player.PlayerEvent;
import net.neoforged.neoforge.registries.DeferredRegister;
import java.util.function.Consumer;

/** Real survival players, drops, effects and inventories. Not a simulated human playthrough. */
final class DiscoveryTests {
    static void register(DeferredRegister<Consumer<GameTestHelper>> f){
        f.register("discovery_menu",()->DiscoveryTests::menu);f.register("discovery_abilities",()->DiscoveryTests::abilities);f.register("discovery_costs",()->DiscoveryTests::costs);
        f.register("discovery_crops",()->DiscoveryTests::crops);f.register("discovery_forestry",()->DiscoveryTests::forestry);f.register("discovery_prestige",()->DiscoveryTests::prestige);
        f.register("discovery_engineering",()->DiscoveryTests::engineering);f.register("discovery_purify",()->DiscoveryTests::purify);f.register("discovery_herd",()->DiscoveryTests::herd);
        f.register("discovery_anomalies",()->DiscoveryTests::anomalies);f.register("discovery_artisan",()->DiscoveryTests::artisan);f.register("discovery_players",()->DiscoveryTests::players);
    }
    private static void check(GameTestHelper h,boolean ok,String message){h.assertTrue(ok,Component.literal(message));}
    private static void learn(ServerPlayer p,Mastery mastery){var m=MasteryProgress.empty().award(Experience.threshold(100)).learn(Talent.EFFICIENCY).learn(Talent.INSIGHT).learn(Talent.passive(mastery)).learn(Talent.ability(mastery));p.setData(PlayerProgression.PROFILE,p.getData(PlayerProgression.PROFILE).with(mastery,m));}
    private static void menu(GameTestHelper h){var p=GameplayTests.player(h);try{learn(p,Mastery.MINING);var menu=new MasteryMenu(44,p.getInventory());check(h,!menu.clickMenuButton(p,Mastery.MINING.ordinal()*Talent.values().length+Talent.FISHING_DIVER.ordinal()),"Foreign mastery talent packets cannot spend points or cross branches");check(h,!menu.clickMenuButton(p,-1)&&!menu.clickMenuButton(p,Integer.MAX_VALUE),"Unbounded talent and action indices are rejected");p.getInventory().setItem(0,new ItemStack(Items.DIAMOND_PICKAXE));check(h,menu.clickMenuButton(p,2000)&&p.hasEffect(MobEffects.HASTE),"The unlocked native menu activates the mining ability");check(h,!menu.clickMenuButton(p,2000),"Rapid button repeats cannot bypass the shared cooldown");}finally{GameplayTests.cleanup(p);}h.succeed();}
    private static void abilities(GameTestHelper h){var p=GameplayTests.player(h);try{check(h,!MasteryAbilities.activate(p,Mastery.DEFENSE),"Locked ability has no effect");learn(p,Mastery.DEFENSE);check(h,MasteryAbilities.activate(p,Mastery.DEFENSE)&&p.hasEffect(MobEffects.ABSORPTION)&&p.getAbsorptionAmount()==8,"Aegis adds four real temporary hearts");learn(p,Mastery.BUILDING);check(h,!MasteryAbilities.activate(p,Mastery.BUILDING),"Cooldown is shared across masteries");p.setData(MasteryAbilities.NEXT,0L);check(h,MasteryAbilities.activate(p,Mastery.BUILDING)&&p.hasEffect(MobEffects.SLOW_FALLING),"Building grants native slow falling");p.setGameMode(net.minecraft.world.level.GameType.SPECTATOR);p.setData(MasteryAbilities.NEXT,0L);check(h,!MasteryAbilities.activate(p,Mastery.BUILDING),"Spectator mode cannot execute resource abilities");}finally{GameplayTests.cleanup(p);}h.succeed();}
    private static void costs(GameTestHelper h){var p=GameplayTests.player(h);try{learn(p,Mastery.CRAFTING);var tool=new ItemStack(Items.DIAMOND_PICKAXE);tool.setDamageValue(800);p.setItemInHand(InteractionHand.MAIN_HAND,tool);long xp=p.getData(PlayerProgression.PROFILE).get(Mastery.CRAFTING).experience();check(h,!MasteryAbilities.activate(p,Mastery.CRAFTING)&&tool.getDamageValue()==800&&p.getData(MasteryAbilities.NEXT)==0,"Missing alloy neither repairs equipment nor starts cooldown");p.getInventory().setItem(8,new ItemStack(ModContent.TEMPERED_ALLOY.get(),2));check(h,MasteryAbilities.activate(p,Mastery.CRAFTING)&&tool.getDamageValue()==800-tool.getMaxDamage()/4&&p.getInventory().getItem(8).getCount()==1,"Repair consumes exactly one alloy for one quarter of native maximum durability");check(h,!MasteryAbilities.activate(p,Mastery.CRAFTING)&&p.getInventory().getItem(8).getCount()==1,"Rejected repeat cannot consume material twice");check(h,p.getData(PlayerProgression.PROFILE).get(Mastery.CRAFTING).experience()==xp,"Ability use never grants craft experience");}finally{GameplayTests.cleanup(p);}h.succeed();}
    private static void crops(GameTestHelper h){var p=GameplayTests.player(h);var w=h.getLevel();var at=h.absolutePos(new BlockPos(5,2,5));w.setBlock(at.below(),Blocks.FARMLAND.defaultBlockState(),3);w.setBlock(at,Blocks.WHEAT.defaultBlockState().setValue(CropBlock.AGE,7),3);p.setPos(Vec3.atBottomCenterOf(at.south(2)));p.setShiftKeyDown(true);learn(p,Mastery.FARMING);p.getInventory().setItem(8,new ItemStack(Items.WHEAT_SEEDS,3));w.destroyBlock(at,true,p);
        h.runAfterDelay(3,()->{try{check(h,w.getBlockState(at).is(Blocks.WHEAT)&&w.getBlockState(at).getValue(CropBlock.AGE)==0,"A real mature harvest replants a native age-zero crop");check(h,p.getInventory().getItem(8).getCount()==2,"Replant consumes one pre-existing seed, not a generated reward");p.setShiftKeyDown(false);w.destroyBlock(at,false,p);w.setBlock(at,Blocks.WHEAT.defaultBlockState(),3);p.getInventory().setItem(8,new ItemStack(Items.BONE_MEAL,4));long xp=p.getData(PlayerProgression.PROFILE).get(Mastery.FARMING).experience();check(h,MasteryAbilities.activate(p,Mastery.FARMING)&&w.getBlockState(at).getValue(CropBlock.AGE)==1&&p.getInventory().getItem(8).isEmpty(),"Verdant breath advances exactly one stage and consumes four bone meal");check(h,p.getData(PlayerProgression.PROFILE).get(Mastery.FARMING).experience()==xp,"Growing a crop through an ability does not award harvest experience");}finally{GameplayTests.cleanup(p);}h.succeed();});}
    private static void forestry(GameTestHelper h){var p=GameplayTests.player(h);var w=h.getLevel();var at=h.absolutePos(new BlockPos(7,2,7));w.setBlock(at.below(),Blocks.DIRT.defaultBlockState(),3);w.setBlock(at,Blocks.OAK_LOG.defaultBlockState(),3);p.setShiftKeyDown(true);learn(p,Mastery.LOGGING);p.getInventory().setItem(8,new ItemStack(Items.OAK_SAPLING,2));w.destroyBlock(at,true,p);
        h.runAfterDelay(3,()->{try{check(h,w.getBlockState(at).is(Blocks.OAK_SAPLING)&&p.getInventory().getItem(8).getCount()==1,"Natural root harvest consumes one real sapling and plants it on valid ground");w.destroyBlock(at,false);w.setBlock(at,Blocks.OAK_LOG.defaultBlockState(),3);w.getChunkAt(at).setData(ProgressionEvents.PLACED,java.util.List.of(at.asLong()));w.destroyBlock(at,true,p);check(h,w.getBlockState(at).isAir()&&p.getInventory().getItem(8).getCount()==1,"Player-placed logs cannot trigger the natural forestry benefit");}finally{GameplayTests.cleanup(p);}h.succeed();});}
    private static void prestige(GameTestHelper h){var p=GameplayTests.player(h);try{learn(p,Mastery.MINING);check(h,Prestige.select(p,0,0)&&p.getInventory().countItem(Prestige.SEALS.get(0).get().asItem())==1,"Level 100 grants an actual luminous decorative seal");check(h,Prestige.select(p,0,0)&&p.getInventory().countItem(Prestige.SEALS.get(0).get().asItem())==1,"Repeated selections cannot mint seals");learn(p,Mastery.FISHING);check(h,Prestige.select(p,3,0)&&p.getInventory().countItem(Prestige.SEALS.get(0).get().asItem())==1,"Changing mastery title does not repeat a milestone reward");check(h,!Prestige.select(p,0,1)&&!Prestige.select(p,15,0)&&!Prestige.select(p,0,4),"Unreached prestige tiers and forged indices are rejected");var out=net.minecraft.world.level.storage.TagValueOutput.createWithContext(net.minecraft.util.ProblemReporter.DISCARDING,h.getLevel().registryAccess());p.saveWithoutId(out);var clone=new ServerPlayer(h.getLevel().getServer(),h.getLevel(),p.getGameProfile(),p.clientInformation());clone.load(net.minecraft.world.level.storage.TagValueInput.create(net.minecraft.util.ProblemReporter.DISCARDING,h.getLevel().registryAccess(),out.buildResult()));check(h,clone.getData(Prestige.REWARDS)==1&&clone.getData(Prestige.SELECTION)==12,"Native player reload retains title and claimed milestones");}finally{GameplayTests.cleanup(p);}h.succeed();}
    private static void engineering(GameTestHelper h){var p=GameplayTests.player(h);var w=h.getLevel();var at=h.absolutePos(new BlockPos(9,2,9));w.setBlock(at,MachineRegistry.EXTRACTOR.get().defaultBlockState(),3);var machine=(ExtractorBlockEntity)w.getBlockEntity(at);try{int original=machine.periodTicks();learn(p,Mastery.ENGINEERING);machine.tune(p);check(h,machine.periodTicks()<original,"Specialist tuning changes real extractor cycle time");int tuned=machine.periodTicks();machine.tune(p);check(h,machine.periodTicks()==tuned,"Reopening the extractor cannot stack tuning");var copy=net.minecraft.world.level.block.entity.BlockEntity.loadStatic(at,machine.getBlockState(),machine.saveWithFullMetadata(w.registryAccess()),w.registryAccess());check(h,copy instanceof ExtractorBlockEntity e&&e.periodTicks()==tuned,"Native reload preserves advanced calibration");}finally{GameplayTests.cleanup(p);}h.succeed();}
    private static void purify(GameTestHelper h){var p=GameplayTests.player(h);try{learn(p,Mastery.ALCHEMY);MasteryAbilities.effect(p,MobEffects.POISON,200,0);check(h,!MasteryAbilities.activate(p,Mastery.ALCHEMY)&&p.hasEffect(MobEffects.POISON),"Purification requires an actual honey bottle");p.getInventory().setItem(8,new ItemStack(Items.HONEY_BOTTLE));check(h,MasteryAbilities.activate(p,Mastery.ALCHEMY)&&!p.hasEffect(MobEffects.POISON)&&p.getInventory().countItem(Items.HONEY_BOTTLE)==0&&p.getInventory().countItem(Items.GLASS_BOTTLE)==1,"Purification removes poison, consumes honey and returns exactly one bottle");}finally{GameplayTests.cleanup(p);}h.succeed();}
    private static void herd(GameTestHelper h){var p=GameplayTests.player(h);var w=h.getLevel();var at=h.absolutePos(new BlockPos(8,2,8));FieldworkTests.platform(w,at);p.setPos(Vec3.atBottomCenterOf(at));var cow=EntityTypes.COW.create(w,EntitySpawnReason.EVENT);cow.setNoAi(true);cow.setPos(Vec3.atBottomCenterOf(at.east(2)));check(h,w.addFreshEntity(cow),"The native herd fixture inserts a real cow in its own loaded chunk");cow.setHealth(2);learn(p,Mastery.BREEDING);p.getInventory().setItem(8,new ItemStack(Items.WHEAT,4));
        h.succeedWhen(()->{check(h,w.getEntitiesOfClass(net.minecraft.world.entity.animal.Animal.class,p.getBoundingBox().inflate(8)).contains(cow),"The test waits for native entity visibility in its isolated pen");check(h,MasteryAbilities.activate(p,Mastery.BREEDING)&&cow.getHealth()==6&&p.getInventory().getItem(8).isEmpty(),"Herd care heals a real animal and consumes four wheat without breeding or spawning loot");cow.discard();GameplayTests.cleanup(p);FieldworkTests.release(w,at);});}
    private static void anomalies(GameTestHelper h){var w=FieldworkTests.vestige(h);var r=fr.axephir.tnd.city.CityRegions.region(61,63);var at=new BlockPos(r.x(),100,r.z());FieldworkTests.platform(w,at);var p=FieldworkTests.player(h,w,at.south(2));var chunk=w.getChunkAt(at);boolean previous=chunk.getData(fr.axephir.tnd.city.CityRegions.GENERATED);try{w.setBlock(at.below(),Blocks.STONE.defaultBlockState(),3);w.setBlock(at,Blocks.IRON_DOOR.defaultBlockState(),3);w.setBlock(at.above(),Blocks.IRON_DOOR.defaultBlockState().setValue(DoorBlock.HALF,net.minecraft.world.level.block.state.properties.DoubleBlockHalf.UPPER),3);p.setData(RareAnomalies.ORIGIN,at);chunk.setData(fr.axephir.tnd.city.CityRegions.GENERATED,false);check(h,!RareAnomalies.stirDoor(p)&&!w.getBlockState(at).getValue(DoorBlock.OPEN),"An anomaly cannot operate a player's door in an old unmarked chunk");chunk.setData(fr.axephir.tnd.city.CityRegions.GENERATED,true);check(h,RareAnomalies.stirDoor(p)&&w.getBlockState(at).getValue(DoorBlock.OPEN),"A natural protected city door can open without replacing any structure");check(h,!RareAnomalies.stirDoor(p)&&w.getBlockState(at).getValue(DoorBlock.OPEN),"Anomaly never closes a door onto a player");}finally{chunk.setData(fr.axephir.tnd.city.CityRegions.GENERATED,previous);GameplayTests.cleanup(p);FieldworkTests.release(w,at);}h.succeed();}
    private static void artisan(GameTestHelper h){var p=GameplayTests.player(h);try{
        learn(p,Mastery.CRAFTING);var at=h.absolutePos(new BlockPos(3,2,3));h.getLevel().setBlock(at,Blocks.CRAFTING_TABLE.defaultBlockState(),3);
        var menu=new net.minecraft.world.inventory.CraftingMenu(78,p.getInventory(),net.minecraft.world.inventory.ContainerLevelAccess.create(h.getLevel(),at));p.containerMenu=menu;
        for(int slot:new int[]{1,2,3})menu.getSlot(slot).set(new ItemStack(Items.IRON_INGOT));for(int slot:new int[]{5,8})menu.getSlot(slot).set(new ItemStack(Items.STICK));
        check(h,menu.getSlot(0).getItem().is(Items.IRON_PICKAXE),"The actual native crafting grid resolves the survival iron pickaxe recipe");
        int base=new ItemStack(Items.IRON_PICKAXE).getMaxDamage();menu.clicked(0,0,net.minecraft.world.inventory.ContainerInput.PICKUP,p);var item=menu.getCarried();
        check(h,item.is(Items.IRON_PICKAXE)&&item.getMaxDamage()==base+base/10,"Taking the actual native recipe result applies artisan durability");
        check(h,java.util.stream.IntStream.rangeClosed(1,9).allMatch(i->menu.getSlot(i).getItem().isEmpty()),"Native crafting consumes the three ingots and two sticks exactly");
        NeoForge.EVENT_BUS.post(new PlayerEvent.ItemCraftedEvent(p,item,new SimpleContainer(9)));check(h,item.getMaxDamage()==base+base/10,"Reprocessing an artisan item cannot stack maximum durability");
        menu.setCarried(ItemStack.EMPTY);p.closeContainer();
    }finally{GameplayTests.cleanup(p);}h.succeed();}
    private static void players(GameTestHelper h){var a=GameplayTests.player(h);var b=GameplayTests.player(h);try{learn(a,Mastery.DEFENSE);learn(b,Mastery.FISHING);check(h,MasteryAbilities.activate(a,Mastery.DEFENSE)&&MasteryAbilities.activate(b,Mastery.FISHING),"Two actual native players have independent cooldowns");check(h,a.hasEffect(MobEffects.ABSORPTION)&&!a.hasEffect(MobEffects.LUCK)&&b.hasEffect(MobEffects.LUCK)&&!b.hasEffect(MobEffects.ABSORPTION),"A player's specialization never buffs another player's private state");check(h,!Prestige.select(b,Mastery.DEFENSE.ordinal(),0),"Other player's mastery cannot unlock prestige");}finally{GameplayTests.cleanup(a);GameplayTests.cleanup(b);}h.succeed();}
    private DiscoveryTests(){}
}
